title:
function lookupStudent(studentID) {
    var students = [
        { id: 14, name: "Kyle" },
        { id: 73, name: "Suzy" },
    ];

    return function greetStudent(greeting) {
        var student = students.find(s => s.id == studentID);
        return `${greeting}, ${student.name}!`;
    };
}

var chosenStudent = lookupStudent(73);

// lookupStudent() 실행은 이미 끝났지만
chosenStudent("Hello"); // "Hello, Suzy!" — students, studentID에 여전히 접근 가능

