function adder(num1) {
    return function addTo(num2) {
        return num1 + num2;
    };
}

var add10To = adder(10); // addTo 인스턴스 1 → num1=10 클로저
var add42To = adder(42); // addTo 인스턴스 2 → num1=42 클로저

add10To(15); // 25
add42To(9);  // 51

